import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { DriftPrint } from '../types'
import {
  addPrint,
  categoryTokens,
  diffPrints,
  dumpFolder,
  dumpName,
  dumpText,
  effortText,
  hasDrift,
  historyText,
  modeOf,
  parseStored,
  referenceFor,
  report,
  sectionPrints,
  shippedPart,
  summary,
  toolPrints,
  upsert,
  USAGE,
} from './logic'

const COMMAND = 'drift'
const STORE_KEY = 'fingerprints'
const TOAST_MS = 10_000
/** A built-in tool's provider; an MCP server's or a plugin's tool is the person's setup, not the build. */
const ENGINE = 'engine'
const PROMPT_ROW = 'System prompt'
const TOOLS_ROW = 'System tools'

const sections = atom({ plugin: 'drift-radar', key: 'sections' } as const, [])
const tools = atom({ plugin: 'drift-radar', key: 'tools' } as const, [])
const lastStep = atom({ plugin: 'drift-radar', key: 'lastStep' } as const, null)
const printedModel = atom({ plugin: 'drift-radar', key: 'printedModel' } as const, null)
const mode = atom({ plugin: 'drift-radar', key: 'mode' } as const, 'interactive')

type Settings = { toasts: boolean; dumpDir: string }

async function startSession($: EngineInterface, isInteractive: boolean): Promise<void> {
  await update($, sections, () => [])
  await update($, tools, () => [])
  await update($, lastStep, () => null)
  await update($, printedModel, () => null)
  await update($, mode, () => modeOf(isInteractive))
  await $.command.register({ name: COMMAND, description: 'Show what changed in the system prompt, tools, model and effort', argumentHint: '[history|dump]' })
}

async function noteSection($: EngineInterface, id: string, text: string | null): Promise<void> {
  await update($, sections, list => (text === null ? list.filter(section => section.id !== id) : upsert(list, { id, text }, 'id')))
}

async function noteTool($: EngineInterface, name: string, description: string, isDeferred: boolean): Promise<void> {
  await update($, tools, list => upsert(list, { name, description, isDeferred }, 'name'))
}

async function noteStep($: EngineInterface, model: string, effort: string | null): Promise<void> {
  await update($, lastStep, () => ({ model, effort }))
}

/** Takes the session's fingerprint once per model, stores it, and toasts what drifted since the last comparable session. */
async function fingerprint($: EngineInterface, settings: Settings): Promise<void> {
  const step = await read($, lastStep)

  if (step === null || (await read($, printedModel)) === step.model) {
    return
  }

  await update($, printedModel, () => step.model)
  const usage = await $.session.usage({ breakdown: 'summary' })
  const categories = usage.context.breakdown?.categories ?? []
  const print: DriftPrint = {
    at: await $.clock.now(),
    sessionId: await $.session.id(),
    version: (await $.session.version()).version,
    model: step.model,
    effort: step.effort,
    mode: await read($, mode),
    promptTokens: categoryTokens(categories, PROMPT_ROW),
    toolTokens: categoryTokens(categories, TOOLS_ROW),
    sections: await sectionPrints(await read($, sections)),
    tools: await toolPrints(await read($, tools)),
  }
  const history = parseStored(await $.store.get(STORE_KEY))
  await $.store.set(STORE_KEY, addPrint(history, print))
  const reference = referenceFor(history, print)

  if (reference === null || !settings.toasts) {
    return
  }

  const drift = shippedPart(diffPrints(reference, print))

  if (hasDrift(drift)) {
    $.ui.toast(summary(drift, print), { timeoutMs: TOAST_MS })
  }
}

async function dump($: EngineInterface, settings: Settings): Promise<string> {
  const seenSections = await read($, sections)
  const seenTools = await read($, tools)

  if (seenSections.length === 0 && seenTools.length === 0) {
    return 'Nothing to dump yet: the prompt is assembled with the first request. Send one prompt, then run /drift dump.'
  }

  const folder = dumpFolder(settings.dumpDir, await $.env.get('HOME'))

  if (folder === null) {
    return 'HOME is not set: set dumpDir in the plugin settings to choose a folder.'
  }

  const version = (await $.session.version()).version
  const model = (await read($, lastStep))?.model ?? (await $.session.model())
  const at = await $.clock.now()
  const path = `${folder}/${dumpName(version, model, at)}`
  await $.fs.write(path, dumpText({ version, model, at, sections: seenSections, tools: seenTools }))

  return `Wrote ${path}\nShipped sections and built-in tool descriptions in full; your own sections by size only. Compare two dumps with git diff --no-index.`
}

async function answer($: EngineInterface, args: string, settings: Settings): Promise<string> {
  const action = args.trim().toLowerCase()

  if (action === 'dump') {
    return dump($, settings)
  }

  const history = parseStored(await $.store.get(STORE_KEY))
  const sessionId = await $.session.id()

  if (action === 'history') {
    return historyText(history, sessionId)
  }

  if (action !== '') {
    return USAGE
  }

  const mine = history.filter(print => print.sessionId === sessionId)
  const current = mine[mine.length - 1] ?? history[history.length - 1] ?? null

  return report(current, history, mine.length > 0)
}

export const register: Register = (on, options) => {
  const settings: Settings = { toasts: options.toast !== false, dumpDir: String(options.dumpDir ?? '') }

  on('session.start', async ($, e, next) => {
    await startSession($, e.isInteractive)

    return next(e)
  })

  on('prompt.section', async ($, e, next) => {
    const result = await next(e)
    await noteSection($, e.name, result.text)

    return result
  })

  on('tool.describe', async ($, e, next) => {
    const result = await next(e)

    if (e.provider.plugin === ENGINE) {
      await noteTool($, e.tool, result.description, (result.isDeferred ?? e.isDeferred) === true)
    }

    return result
  })

  on('turn.step', async function* ($, e, next) {
    if (e.agentId === undefined) {
      await noteStep($, e.model, effortText(e.effort))
    }

    return yield* next(e)
  })

  on('turn.complete', async ($, e, next) => {
    // A request that failed (expired login, no network) can run with fewer tools; the next answered turn takes the print.
    if (e.agentId === undefined && e.reason !== 'error') {
      await fingerprint($, settings)
    }

    return next(e)
  })

  on('command.run', { command: COMMAND }, async ($, e) => ({ text: await answer($, e.args, settings) }))
}

