import type { DriftMode, DriftPrint, DriftScope, DriftSection, DriftSectionText, DriftTool, DriftToolText } from '../types'

/** Fingerprints kept in the store; older ones are dropped first. */
export const MAX_PRINTS = 30
/** Hex digits of the SHA-256 kept per section or tool: enough to tell texts apart, short enough to store 30 sessions. */
const HASH_HEX = 12
/**
 * A change in the /context estimate of the whole system prompt below this is
 * left out of the toast: your folder path and the date move it by a few tokens.
 */
export const PROMPT_NOISE_TOKENS = 100
const THOUSAND = 1000
/** Up to this many changed tools are named in the toast; more are counted. */
const TOOLS_NAMED = 3
const DATE_END = 10
const MINUTE_END = 16

/**
 * Sections whose text comes from you, not from the build: your CLAUDE.md files,
 * your folder, platform and date, the skills and MCP servers you set up, your
 * output style and language. Matched on the name before its first `:`.
 */
const SESSION_SECTIONS: readonly string[] = [
  'memory',
  'env_info',
  'env_info_simple',
  'session_guidance',
  'mcp_instructions',
  'output_style',
  'language',
  'scratchpad',
]

const baseOf = (id: string): string => id.split(':')[0] ?? id

export const scopeOf = (id: string): DriftScope => (SESSION_SECTIONS.includes(baseOf(id)) ? 'session' : 'shipped')

export type Change = { before: string; after: string }
export type Count = { before: number; after: number }
export type SectionChange = { id: string; formerId: string | null; scope: DriftScope; before: number; after: number }
export type ToolChange = { name: string; before: number; after: number; isTextChanged: boolean; deferral: Change | null }

export type Drift = {
  version: Change | null
  model: Change | null
  effort: Change | null
  promptTokens: Count | null
  toolTokens: Count | null
  sectionsAdded: DriftSection[]
  sectionsRemoved: DriftSection[]
  sectionsChanged: SectionChange[]
  toolsAdded: DriftTool[]
  toolsRemoved: DriftTool[]
  toolsChanged: ToolChange[]
}

const toHex = (bytes: ArrayBuffer): string =>
  [...new Uint8Array(bytes)].map(byte => byte.toString(16).padStart(2, '0')).join('')

/** A short SHA-256 of the text: two texts with one hash are taken as equal. */
export const shortHash = async (text: string): Promise<string> =>
  toHex(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text))).slice(0, HASH_HEX)

export const effortText = (effort: string | number | undefined): string | null =>
  effort === undefined ? null : String(effort)

export const sectionPrints = (sections: readonly DriftSectionText[]): Promise<DriftSection[]> =>
  Promise.all(
    sections.map(async section => ({ id: section.id, scope: scopeOf(section.id), chars: section.text.length, hash: await shortHash(section.text) })),
  )

export const toolPrints = (tools: readonly DriftToolText[]): Promise<DriftTool[]> =>
  Promise.all(
    [...tools]
      .sort((a, b) => a.name.localeCompare(b.name))
      .map(async tool => ({ name: tool.name, chars: tool.description.length, hash: await shortHash(tool.description), isDeferred: tool.isDeferred })),
  )

/** Keeps the latest text per id: a section or tool described twice counts once. */
export const upsert = <T, K extends keyof T>(list: readonly T[], item: T, key: K): T[] => [
  ...list.filter(other => other[key] !== item[key]),
  item,
]

/** 480, 1.2k, 31k: a size as the toast spells it. */
export const compactChars = (chars: number): string => {
  const size = Math.abs(chars)

  if (size < THOUSAND) {
    return String(size)
  }

  return `${(size / THOUSAND).toFixed(1).replace(/\.0$/, '')}k`
}

export const signed = (amount: number): string => (amount === 0 ? '±0' : `${amount > 0 ? '+' : '-'}${compactChars(amount)}`)

const changeOf = (before: string | null, after: string | null): Change | null =>
  before === after ? null : { before: before ?? 'none', after: after ?? 'none' }

const countOf = (before: number | null, after: number | null): Count | null =>
  before === null || after === null || before === after ? null : { before, after }

const deferralOf = (isDeferred: boolean): string => (isDeferred ? 'deferred' : 'listed')

/**
 * Sections keyed by the name before the first `:`, so `communication:L` on one
 * build and `communication` on the next are one section; a base two sections
 * share keeps their full ids. The id is never sent to the model, the text is.
 */
const sectionsByKey = (sections: readonly DriftSection[]): Map<string, DriftSection> => {
  const counts = new Map<string, number>()

  for (const section of sections) {
    counts.set(baseOf(section.id), (counts.get(baseOf(section.id)) ?? 0) + 1)
  }

  return new Map(sections.map(section => [counts.get(baseOf(section.id)) === 1 ? baseOf(section.id) : section.id, section]))
}

/** Every difference between two fingerprints, in the order the newer one lists them. */
export const diffPrints = (before: DriftPrint, after: DriftPrint): Drift => {
  const oldSections = sectionsByKey(before.sections)
  const newSections = sectionsByKey(after.sections)
  const oldTools = new Map(before.tools.map(tool => [tool.name, tool]))
  const newTools = new Map(after.tools.map(tool => [tool.name, tool]))
  const sectionsChanged: SectionChange[] = []
  const toolsChanged: ToolChange[] = []

  for (const [key, section] of newSections) {
    const old = oldSections.get(key)

    if (old !== undefined && old.hash !== section.hash) {
      const formerId = old.id === section.id ? null : old.id
      sectionsChanged.push({ id: section.id, formerId, scope: section.scope, before: old.chars, after: section.chars })
    }
  }

  for (const tool of after.tools) {
    const old = oldTools.get(tool.name)

    if (old !== undefined && (old.hash !== tool.hash || old.isDeferred !== tool.isDeferred)) {
      toolsChanged.push({
        name: tool.name,
        before: old.chars,
        after: tool.chars,
        isTextChanged: old.hash !== tool.hash,
        deferral: changeOf(deferralOf(old.isDeferred), deferralOf(tool.isDeferred)),
      })
    }
  }

  return {
    version: changeOf(before.version, after.version),
    model: changeOf(before.model, after.model),
    effort: changeOf(before.effort, after.effort),
    promptTokens: countOf(before.promptTokens, after.promptTokens),
    toolTokens: countOf(before.toolTokens, after.toolTokens),
    sectionsAdded: [...newSections].filter(([key]) => !oldSections.has(key)).map(([, section]) => section),
    sectionsRemoved: [...oldSections].filter(([key]) => !newSections.has(key)).map(([, section]) => section),
    sectionsChanged,
    toolsAdded: after.tools.filter(tool => !oldTools.has(tool.name)),
    toolsRemoved: before.tools.filter(tool => !newTools.has(tool.name)),
    toolsChanged,
  }
}

/**
 * The part of a drift that ships with the build: shipped sections, built-in
 * tools and a prompt estimate that moved past the noise. Session sections are yours.
 */
export const shippedPart = (drift: Drift): Drift => ({
  ...drift,
  promptTokens:
    drift.promptTokens !== null && Math.abs(drift.promptTokens.after - drift.promptTokens.before) >= PROMPT_NOISE_TOKENS
      ? drift.promptTokens
      : null,
  toolTokens: null,
  sectionsAdded: drift.sectionsAdded.filter(section => section.scope === 'shipped'),
  sectionsRemoved: drift.sectionsRemoved.filter(section => section.scope === 'shipped'),
  sectionsChanged: drift.sectionsChanged.filter(section => section.scope === 'shipped'),
})

const sectionCount = (drift: Drift): number =>
  drift.sectionsAdded.length + drift.sectionsRemoved.length + drift.sectionsChanged.length

const toolCount = (drift: Drift): number => drift.toolsAdded.length + drift.toolsRemoved.length + drift.toolsChanged.length

/** Whether the model was given something different; a version bump alone is not. */
export const hasDrift = (drift: Drift): boolean =>
  drift.effort !== null ||
  drift.model !== null ||
  drift.promptTokens !== null ||
  drift.toolTokens !== null ||
  sectionCount(drift) > 0 ||
  toolCount(drift) > 0

const sectionDelta = (drift: Drift): number =>
  drift.sectionsAdded.reduce((sum, section) => sum + section.chars, 0) -
  drift.sectionsRemoved.reduce((sum, section) => sum + section.chars, 0) +
  drift.sectionsChanged.reduce((sum, section) => sum + section.after - section.before, 0)

const plural = (count: number, word: string): string => `${count} ${word}${count === 1 ? '' : 's'}`

const named = (names: readonly string[], one: string, many: string): string =>
  names.length <= TOOLS_NAMED ? `${names.join(', ')} ${names.length === 1 ? one : many}` : `${names.length} ${many}`

/** The one line a toast shows, e.g. `drift: 2.1.284 → 2.1.285 · prompt +1.2k chars (2 sections) · Bash description changed`. */
export const summary = (drift: Drift, after: DriftPrint): string => {
  const parts = [drift.version === null ? `drift on ${after.version}` : `drift: ${drift.version.before} → ${drift.version.after}`]

  if (drift.model !== null) {
    parts.push(`model ${drift.model.before} → ${drift.model.after}`)
  }

  const sections = sectionCount(drift)

  if (sections > 0) {
    parts.push(`prompt ${signed(sectionDelta(drift))} chars (${plural(sections, 'section')})`)
  }

  if (drift.promptTokens !== null) {
    parts.push(`system prompt ${signed(drift.promptTokens.after - drift.promptTokens.before)} tokens`)
  }

  const rewritten = drift.toolsChanged.filter(tool => tool.isTextChanged).map(tool => tool.name)
  const moved = drift.toolsChanged.filter(tool => tool.deferral !== null)

  if (rewritten.length > 0) {
    parts.push(named(rewritten, 'description changed', 'tool descriptions changed'))
  }

  for (const tool of moved) {
    parts.push(`${tool.name} now ${tool.deferral?.after ?? ''}`)
  }

  if (drift.toolsAdded.length > 0) {
    parts.push(named(drift.toolsAdded.map(tool => tool.name), 'tool added', 'tools added'))
  }

  if (drift.toolsRemoved.length > 0) {
    parts.push(named(drift.toolsRemoved.map(tool => tool.name), 'tool removed', 'tools removed'))
  }

  if (drift.effort !== null) {
    parts.push(`effort ${drift.effort.before} → ${drift.effort.after}`)
  }

  return parts.join(' · ')
}

/** Two prints compare only on one model and one mode: `-p` and the REPL assemble different prompts. */
export const profileOf = (print: DriftPrint): string => `${print.model}|${print.mode}`

const latest = (prints: readonly DriftPrint[], keep: (print: DriftPrint) => boolean): DriftPrint | null =>
  prints.reduce<DriftPrint | null>((best, print) => (keep(print) && (best === null || print.at > best.at) ? print : best), null)

const earlier = (history: readonly DriftPrint[], print: DriftPrint): DriftPrint[] =>
  history.filter(other => other !== print && other.at < print.at)

/** The last earlier session on the same model and mode: what a toast compares with. */
export const referenceFor = (history: readonly DriftPrint[], print: DriftPrint): DriftPrint | null =>
  latest(earlier(history, print), other => profileOf(other) === profileOf(print))

/** The last earlier session on another version or model. */
export const baselineFor = (history: readonly DriftPrint[], print: DriftPrint): DriftPrint | null =>
  latest(earlier(history, print), other => other.version !== print.version || other.model !== print.model)

export const addPrint = (history: readonly DriftPrint[], print: DriftPrint): DriftPrint[] =>
  [...history, print].sort((a, b) => a.at - b.at).slice(-MAX_PRINTS)

const isRecord = (value: unknown): value is Record<string, unknown> => typeof value === 'object' && value !== null

const isCount = (value: unknown): value is number | null => value === null || typeof value === 'number'

const isSection = (value: unknown): value is DriftSection =>
  isRecord(value) &&
  typeof value.id === 'string' &&
  (value.scope === 'shipped' || value.scope === 'session') &&
  typeof value.chars === 'number' &&
  typeof value.hash === 'string'

const isTool = (value: unknown): value is DriftTool =>
  isRecord(value) &&
  typeof value.name === 'string' &&
  typeof value.chars === 'number' &&
  typeof value.hash === 'string' &&
  typeof value.isDeferred === 'boolean'

const isPrint = (value: unknown): value is DriftPrint =>
  isRecord(value) &&
  typeof value.at === 'number' &&
  typeof value.sessionId === 'string' &&
  typeof value.version === 'string' &&
  typeof value.model === 'string' &&
  (value.effort === null || typeof value.effort === 'string') &&
  (value.mode === 'interactive' || value.mode === 'headless') &&
  isCount(value.promptTokens) &&
  isCount(value.toolTokens) &&
  Array.isArray(value.sections) &&
  value.sections.every(isSection) &&
  Array.isArray(value.tools) &&
  value.tools.every(isTool)

/** The store's value as fingerprints, oldest first; anything malformed (an older format, a hand edit) is dropped. */
export const parseStored = (value: unknown): DriftPrint[] =>
  Array.isArray(value) ? value.filter(isPrint).sort((a, b) => a.at - b.at) : []

export const sectionChars = (print: DriftPrint): number => print.sections.reduce((sum, section) => sum + section.chars, 0)

/** `2026-10-06 12:00 UTC`: one zone for every row, so two machines' histories read alike. */
export const when = (at: number): string => {
  const iso = new Date(at).toISOString()

  return `${iso.slice(0, DATE_END)} ${iso.slice(DATE_END + 1, MINUTE_END)} UTC`
}

const printLabel = (print: DriftPrint): string =>
  `${when(print.at)} · ${print.version} · ${print.model} · ${print.mode} · effort ${print.effort ?? 'none'}`

const tokens = (count: number | null): string => (count === null ? '?' : `~${compactChars(count)}`)

const sizeLine = (print: DriftPrint): string =>
  `system prompt ${tokens(print.promptTokens)} tokens, of it ${plural(print.sections.length, 'section')} hooks can see (${compactChars(sectionChars(print))} chars) · ${plural(print.tools.length, 'built-in tool')} ${tokens(print.toolTokens)} tokens`

const yours = (scope: DriftScope): string => (scope === 'session' ? '  (yours)' : '')

const toolLine = (tool: ToolChange): string => {
  const parts: string[] = []

  if (tool.isTextChanged) {
    parts.push(`description ${compactChars(tool.before)} → ${compactChars(tool.after)} chars (${signed(tool.after - tool.before)})`)
  }

  if (tool.deferral !== null) {
    parts.push(`${tool.deferral.before} → ${tool.deferral.after}`)
  }

  return `  ~ tool ${tool.name}: ${parts.join(', ')}`
}

/** The lines of one drift, indented under its heading; empty when nothing differs. */
export const driftLines = (drift: Drift): string[] => {
  const lines: string[] = []

  for (const [label, change] of [['version', drift.version], ['model', drift.model], ['effort', drift.effort]] as const) {
    if (change !== null) {
      lines.push(`  ${label} ${change.before} → ${change.after}`)
    }
  }

  for (const [label, count] of [['system prompt', drift.promptTokens], ['built-in tools', drift.toolTokens]] as const) {
    if (count !== null) {
      lines.push(`  ${label} ~${compactChars(count.before)} → ~${compactChars(count.after)} tokens (${signed(count.after - count.before)})`)
    }
  }

  for (const section of drift.sectionsChanged) {
    const was = section.formerId === null ? '' : ` (was ${section.formerId})`
    lines.push(`  ~ section ${section.id}${was}: ${compactChars(section.before)} → ${compactChars(section.after)} chars (${signed(section.after - section.before)})${yours(section.scope)}`)
  }

  for (const section of drift.sectionsAdded) {
    lines.push(`  + section ${section.id}: ${signed(section.chars)} chars${yours(section.scope)}`)
  }

  for (const section of drift.sectionsRemoved) {
    lines.push(`  - section ${section.id}: ${signed(-section.chars)} chars${yours(section.scope)}`)
  }

  lines.push(...drift.toolsChanged.map(toolLine))

  for (const tool of drift.toolsAdded) {
    lines.push(`  + tool ${tool.name}: ${signed(tool.chars)} chars${tool.isDeferred ? ', deferred' : ''}`)
  }

  for (const tool of drift.toolsRemoved) {
    lines.push(`  - tool ${tool.name}: ${signed(-tool.chars)} chars`)
  }

  return lines
}

const block = (heading: string, before: DriftPrint, after: DriftPrint): string[] => {
  const lines = driftLines(diffPrints(before, after))

  return [`${heading} (${printLabel(before)}):`, ...(lines.length === 0 ? ['  nothing changed'] : lines)]
}

export const NO_PRINTS = 'No fingerprint yet: drift-radar takes one after the first answer of a session.'

/** What `/drift` prints: the current fingerprint against the last comparable session and the last other version or model. */
export const report = (current: DriftPrint | null, history: readonly DriftPrint[], isThisSession: boolean): string => {
  if (current === null) {
    return NO_PRINTS
  }

  const lines = [`${isThisSession ? 'This session' : 'Latest session'}: ${printLabel(current)}`, sizeLine(current)]
  const reference = referenceFor(history, current)
  const baseline = baselineFor(history, current)

  if (reference === null && baseline === null) {
    lines.push('', 'Nothing earlier to compare with yet. The next session or the next update will have a diff.')

    return lines.join('\n')
  }

  if (reference !== null) {
    lines.push('', ...block('Since the last session on this model and mode', reference, current))
  }

  if (baseline !== null && baseline !== reference) {
    lines.push('', ...block('Since the last other version or model', baseline, current))
  }

  lines.push('', '(yours) = a section built from your files, folder, date or setup: shown here, never toasted.')

  return lines.join('\n')
}

/** What `/drift history` prints: one row per stored fingerprint, newest first. */
export const historyText = (history: readonly DriftPrint[], sessionId: string): string => {
  if (history.length === 0) {
    return NO_PRINTS
  }

  const rows = [...history].reverse().map(print => {
    const mark = print.sessionId === sessionId ? '*' : ' '

    return `${mark} ${when(print.at)}  ${print.version}  ${print.model}  ${print.mode}  effort ${print.effort ?? 'none'}  prompt ${tokens(print.promptTokens)} tokens  ${plural(print.tools.length, 'tool')}`
  })

  return [`${plural(history.length, 'fingerprint')} stored (max ${MAX_PRINTS}), newest first; * = this session`, ...rows].join('\n')
}

const unsafe = /[^A-Za-z0-9._-]+/g

/** `2.1.285-claude-opus-5-5-2026-10-06.md`: a file name per version, model and day. */
export const dumpName = (version: string, model: string, at: number): string =>
  `${version.replace(unsafe, '_')}-${model.replace(unsafe, '_')}-${new Date(at).toISOString().slice(0, DATE_END)}.md`

/** The folder dumps go to: the setting (with `~/` expanded) or `~/.claude/drift-radar`; null when HOME is needed and unset. */
export const dumpFolder = (setting: string, home: string | undefined): string | null => {
  const chosen = setting.trim().replace(/\/+$/, '')

  if (chosen === '') {
    return home === undefined ? null : `${home}/.claude/drift-radar`
  }

  if (chosen.startsWith('~/')) {
    return home === undefined ? null : `${home}/${chosen.slice(2)}`
  }

  return chosen
}

export type DumpInput = {
  version: string
  model: string
  at: number
  sections: readonly DriftSectionText[]
  tools: readonly DriftToolText[]
}

/**
 * The shipped sections and the built-in tools' descriptions in full, as Markdown for `git diff`.
 * Session sections are listed by size only: they hold your CLAUDE.md and paths.
 */
export const dumpText = (input: DumpInput): string => {
  const lines = [`# Claude Code ${input.version} · ${input.model} · ${when(input.at)}`, '', '## System prompt sections', '']

  for (const section of [...input.sections].sort((a, b) => a.id.localeCompare(b.id))) {
    if (scopeOf(section.id) === 'shipped') {
      lines.push(`### ${section.id} (${section.text.length} chars)`, '', section.text, '')
    } else {
      lines.push(`### ${section.id} (${section.text.length} chars, yours: text left out)`, '')
    }
  }

  lines.push('## Built-in tools', '')

  for (const tool of [...input.tools].sort((a, b) => a.name.localeCompare(b.name))) {
    lines.push(`### ${tool.name} (${tool.description.length} chars${tool.isDeferred ? ', deferred' : ''})`, '', tool.description, '')
  }

  return lines.join('\n')
}

/** Picks the /context rows a fingerprint keeps; the rows carry no id, so they are found by label. */
export const categoryTokens = (categories: readonly { name: string; tokens: number }[], name: string): number | null =>
  categories.find(category => category.name === name)?.tokens ?? null

export const modeOf = (isInteractive: boolean): DriftMode => (isInteractive ? 'interactive' : 'headless')

export const USAGE = [
  '/drift          what changed in the system prompt, tools, model and effort',
  '/drift history  the stored fingerprints',
  '/drift dump     write the shipped prompt sections and built-in tool descriptions to a file',
].join('\n')

