/** `shipped` sections read the same for everyone on a build and model; `session` ones carry your files, folder and date. */
export type DriftScope = 'shipped' | 'session'

export type DriftMode = 'interactive' | 'headless'

export type DriftSection = { id: string; scope: DriftScope; chars: number; hash: string }

export type DriftTool = { name: string; chars: number; hash: string; isDeferred: boolean }

/** What the model was given in one session, reduced to sizes and short hashes. */
export type DriftPrint = {
  at: number
  sessionId: string
  version: string
  model: string
  effort: string | null
  mode: DriftMode
  /** The whole system prompt as /context estimates it, the parts no hook sees included. */
  promptTokens: number | null
  toolTokens: number | null
  sections: DriftSection[]
  tools: DriftTool[]
}

/** A system prompt section's text as the engine assembled it this session. */
export type DriftSectionText = { id: string; text: string }

/** A built-in tool's description as the engine rendered it this session. */
export type DriftToolText = { name: string; description: string; isDeferred: boolean }

export type DriftStep = { model: string; effort: string | null }

declare module 'claude-code' {
  interface PluginState {
    'drift-radar': {
      sections: DriftSectionText[]
      tools: DriftToolText[]
      lastStep: DriftStep | null
      printedModel: string | null
      mode: DriftMode
    }
  }
}
